    import re

    # 1) Best-effort dismiss any visible modal/overlay by clicking a likely close button.
    try:
        close_btns = page.get_by_role("button", name=re.compile(r"^(×|x|close|dismiss)$", re.IGNORECASE))
        if await close_btns.count() > 0:
            try:
                await close_btns.first.click(force=True)
            except Exception:
                # ignore and continue
                pass
        else:
            # broader attempt: any button with the substring 'close'
            alt = page.get_by_role("button", name=re.compile(r"close", re.IGNORECASE))
            if await alt.count() > 0:
                try:
                    await alt.first.click(force=True)
                except Exception:
                    pass
    except Exception:
        # Best-effort only; continue even if dismissal fails
        pass

    # 2) Locate complementary region and search input inside it
    comp = page.get_by_role("complementary")
    # wait for the complementary region to be present and visible
    await comp.first.wait_for(state="visible")

    # Prefer role=searchbox named 'Search', fallback to any searchbox, then textbox
    search_input = None
    if await comp.first.get_by_role("searchbox", name="Search").count() > 0:
        search_input = comp.first.get_by_role("searchbox", name="Search").first
    elif await comp.first.get_by_role("searchbox").count() > 0:
