    if await comp.first.get_by_role("button", name=re.compile(r"search", re.IGNORECASE)).count() > 0:
        search_btn = comp.first.get_by_role("button", name=re.compile(r"search", re.IGNORECASE)).first
    elif await comp.first.get_by_role("button").count() > 0:
        # pragmatic fallback: first button inside complementary
        search_btn = comp.first.get_by_role("button").first

    if search_btn is not None:
        try:
            await search_btn.click()
        except Exception:
            # fallback to forced click if obscured
            await search_btn.click(force=True)
    else:
